function readableError(reason:unknown):string{return(reason instanceof Error?reason.message:String(reason)).replace(/^Error invoking remote method '[^']+': Error:\s*/,'')}
function suggestProjectName(prompt:string):string{const words=prompt.replace(/^(build|create|make|design)\s+(me\s+)?(an?\s+)?/i,'').replace(/[^a-zA-Z0-9\s-]/g,'').trim().split(/\s+/).slice(0,4);return words.join(' ')||'My desktop app'}
const textReferenceExtensions=new Set(['txt','md','csv','tsv','json','js','jsx','ts','tsx','css','html','xml','yaml','yml','toml','sql','py','rs','java','cs','cpp','h']);
async function browserAttachments(files:File[]):Promise<AgentAttachment[]>{const result:AgentAttachment[]=[];for(const file of files.slice(0,8)){const name=file.name||`Pasted image ${result.length+1}`,extension=name.split('.').pop()?.toLowerCase()||'',mime=file.type.toLowerCase();if(['image/png','image/jpeg','image/webp'].includes(mime)){if(file.size>5_000_000)throw new Error(`${name} is larger than the 5 MB image limit.`);const dataUrl=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(new Error(`Could not read ${name}.`));reader.readAsDataURL(file)});result.push({name,kind:'image',mimeType:mime,dataUrl})}else if(textReferenceExtensions.has(extension)||mime.startsWith('text/')||['application/json','application/xml','application/yaml','application/toml','application/sql'].includes(mime)){if(file.size>1_000_000)throw new Error(`${name} is larger than the 1 MB text-file limit.`);result.push({name,kind:'text',mimeType:mime||'text/plain',text:await file.text()})}else throw new Error(`${name} is not a supported image, text, code, or data file.`)}return result}

