 async function refreshPreview(){if(!window.foundry?.preview||!project)return;setPreviewBusy(true);setPreviewError('');try{const result=await window.foundry.preview.build(project.id);setPreviewHtml(result.html)}catch(reason){setPreviewError(readableError(reason))}finally{setPreviewBusy(false)}}
 async function runDesktopApp(){if(!window.foundry?.runtime||!project){setError('Create or open a project before running it.');return}setRuntimeBusy(true);setError('');try{await window.foundry.runtime.open(project.id);setNotice(`${project.name} is running in its own desktop window.`);window.setTimeout(()=>setNotice(''),3000)}catch(reason){showError(reason)}finally{setRuntimeBusy(false)}}
 async function buildInstaller(){if(!window.foundry?.installer||!project){setError('Create or open a project before building an installer.');return}setInstallerBusy(true);setError('');setNotice('Preparing the Windows installer…');try{const result=await window.foundry.installer.build(project.id);setNotice(result.signed?'Signed Windows installer and SHA-256 checksum built successfully.':'Windows installer and SHA-256 checksum built successfully (unsigned).');await window.foundry.installer.reveal(result.installerPath)}catch(reason){setNotice('');showError(reason)}finally{setInstallerBusy(false)}}
