 async function fixDiagnostic(){if(!diagnostic||!project||diagnostic.projectId!==project.id)return;const message=diagnostic.message;setDiagnostic(null);await runRequest(`Fix this runtime error. Inspect the relevant project files, make the smallest safe correction, and validate the project before finishing.\n\nRuntime error:\n${message.slice(0,5000)}`)}
 async function saveProjectConfig(e:FormEvent){e.preventDefault();if(!window.foundry?.projectConfig||!project||!config)return;setConfigSaving(true);try{setConfig(await window.foundry.projectConfig.save(project.id,config));setConfigOpen(false);setNotice('App configuration saved.');window.setTimeout(()=>setNotice(''),3000)}catch(reason){showError(reason)}finally{setConfigSaving(false)}}
