 function showError(reason:unknown){setError(readableError(reason))}
 async function createProject(e:FormEvent){e.preventDefault();if(!bridge||!projectName.trim())return;try{const created=await bridge.createProject(projectName.trim(),projectTemplate);if(!created)return;const firstRequest=pendingHomePrompt;setProjects(items=>[created,...items.filter(item=>item.id!==created.id)]);setProject(created);setProjectName('');setPendingHomePrompt('');setDialogOpen(false);setHome(false);setView('preview');if(firstRequest)await runRequest(firstRequest,undefined,created)}catch(reason){showError(reason)}}
