 async function cloudAuth(create:boolean){if(!window.foundry||!cloudEmail.trim()||!cloudPassword)return;setSavingKey(true);try{setSettings(await window.foundry.settings.cloudAuth(cloudEmail.trim(),cloudPassword,create));setCloudPassword('');setNotice(create?'Foundry Cloud account created.':'Signed in to Foundry Cloud.');window.setTimeout(()=>setNotice(''),3000);window.setTimeout(()=>void refreshCloud(),250)}catch(reason){showError(reason)}finally{setSavingKey(false)}}
