 async function buyCredits(packageId:string){if(!window.foundry)return;const startingCredits=settings.hosted.credits;setError('');try{await window.foundry.settings.cloudCheckout(packageId);setNotice('Secure checkout opened. Waiting for payment confirmation…');for(let attempt=0;attempt<60;attempt++){await new Promise(resolve=>window.setTimeout(resolve,3000));const next=await window.foundry.settings.cloudRefresh();setSettings(next);if(next.hosted.credits>startingCredits){const added=next.hosted.credits-startingCredits;setError('');setNotice(`Payment confirmed — ${added.toLocaleString()} credits added.`);window.setTimeout(()=>setNotice(''),8000);return}}setNotice('Checkout is still pending. Use Refresh balance after completing payment.');window.setTimeout(()=>setNotice(''),8000)}catch(reason){showError(reason)}}
 async function runBenchmark(id:string){if(!window.foundry?.benchmarks||benchmarkRunning)return;if(!settings.configured){setSettingsOpen(true);return}const billing=settings.mode==='hosted'?'Foundry Cloud credits':`your ${settings.providers.find(item=>item.id===settings.provider)?.name??'AI'} API key`;if(!window.confirm(`This benchmark creates an isolated test project and uses ${billing}. Run it now?`))return;setBenchmarkRunning(id);setError('');try{setBenchmarkSnapshot(await window.foundry.benchmarks.run(id))}catch(reason){showError(reason)}finally{setBenchmarkRunning('')}}
