 async function runBenchmarkCampaign(){if(!window.foundry?.benchmarks||benchmarkRunning)return;if(!settings.configured){setSettingsOpen(true);return}if(!window.confirm('Run the full reliability campaign? Foundry will generate and verify 30 isolated apps across three cycles. This can take a long time and may use significant AI credits.'))return;setBenchmarkRunning('campaign');setError('');setNotice('Starting the three-cycle reliability campaign…');try{const snapshot=await window.foundry.benchmarks.runCampaign();setBenchmarkSnapshot(snapshot);setNotice(snapshot.releaseReady?'Reliability campaign passed. Foundry meets the release gate.':'Reliability campaign finished below the release gate.')}catch(reason){showError(reason)}finally{setBenchmarkRunning('')}}
